$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$work=Join-Path $root 'grok_inventory_edit';New-Item -ItemType Directory -Path $work -ErrorAction Stop|Out-Null
$src=Join-Path $root 'inventory\device_inventory.py'
$sha=(Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash
$prompt=@'
You are actual GROK corrective CODE EDIT lane after actual Gemini substantive review. Return ONLY valid JSON {"replacements":[{"old":"exact source substring","new":"replacement"}],"test_source":"complete unittest module importing device_inventory actual source, NO STUB","notes":["..."]}. Author minimal exact tested patch, not prose or fullrewrite. No tools/edits yourself/no shell/MCP/web/auth/memory/globalfactory/subagents. Read supplied source only. Owner will apply/gate later. No claimedexecution.

Target ONLY device_inventory.py six concrete admission/identity defects:
1 PCI canonicalization: actual NVIDIA often emits 8hex zero-padded domain00000000:01:00.0. Accept EXACT4hex or8hex domains; normalize numerical PCI segment to canonical LOWERCASE4hex domain (0000:01:00.0) matching AMD/Intel alias. Reject segment numeric>0xffff (do not truncate), PCI device>0x1f, fn>7. Never invent missingdomain0. Gemini suggestion alwayszfill8 is rejected because crossbackend canonical4 contract. MissingPCI remains unqualified.
2 _parse_utc: refuse naive datetime ratherthaninventUTC, require awareparsedtimestamp; strictinput now_utc aware datetime, max_age_seconds finite positive scalar no bool. Allvendorfresh checks need0<=age<=maxage; future/stale nonallocatable.
3 get_admission_snapshot must revalidate physical_id canonical valid and timestamp age against provided NOW on EVERY admission, not trust cached FRESH label. MissingPCI refused, future/stale/unknown timestamp refused, memory_kind mustexplicit DEDICATED, free typeint nonnegative within knownvalid advertised_total and >0, totaltypeintpositive. Revalidate vendor/samplemetadata? nofake source default. Preserve API return shapeeligible/refused.
4 contradiction quarantine: tombstone conflictedPCI IDs for entire normalize batch, thirdsample mustnotresurrect. Detect vendor,total and memorykind contradictions. Multipleconsistentfreshsample memorydata select latesttimestamp rather thanblindfirst, mergedaliases; noclaimdedup byname.
5 unknown classification failclosed: NVIDIA memory_kind absent/invalid=>UNKNOWN, Intel sample explicit memory_kind absent/invalid=>UNKNOWN. AMD explicit dedicated/shared bytefields only already declaredschema; do notguess realvendorCLI schemas. Update original provider testfixtures toexplicitDEDICATED for caseswantcapacity; testsactualimport noaliasesstub. Restrict physicalID actuallyvalidated sourceget.
6 floats fractionalunits mustnottruncate toint silently inbyte/MiBparsers. Reject nonintegralfinite floats, bools, invalidstrings/NaN/negatives. Correct NVIDIA CSV usecsv module notsplit soquotednames parse correctly. Requiredeclaredheader ratherthanguessingoutputwithoutheader. No subprocess/newvendorCLIcommands.

Keep under<=450lines total reconstructedsource. Test module imports actual device_inventory, coversfuturetimestamp, admissionstaleatlaternow, missingID, 8hexNVvs4hexAMDcanonicaldedup, >ffffsegmentrefused, device32invalid, naiveUTCrefused, contradictoryvendor/totalthirdresurrection, explicitUNKNOWNclassification/freeN/A/sharedAMDrefusal, nonintegralfloats, quotedname CSV; sufficientexplicitfreshdedicatedvalid samplesadmit. AllGPUfree nofilewrites/toolcalls. Original14testssomefixtureslackclassification intentionallyupdatefixtureonly notweakenunknown admission. Actual measuredindependent4negativefailures supplied below.
'@
$prompt+="`nEXACT ORIGINAL SOURCE SHA256 $sha`n"+(Get-Content -Raw -LiteralPath $src)+"`nORIGINAL PROVIDER TESTS`n"+(Get-Content -Raw -LiteralPath (Join-Path $root 'inventory\tests.candidate.txt'))+"`nACTUAL GPU-FREE GATE`n"+(Get-Content -Raw -LiteralPath (Join-Path $root 'inventory_gate_receipt.json'))
$pp=Join-Path $work 'request.txt';$prompt|Set-Content -LiteralPath $pp -Encoding utf8
$cfg=Join-Path $work '.grok';New-Item -ItemType Directory -Path $cfg|Out-Null
"[mcp_servers.google_search_console]`nenabled=false`n[mcp_servers.windows-mcp]`nenabled=false`n[mcp_servers.pycharm]`nenabled=false"|Set-Content -LiteralPath (Join-Path $cfg 'config.toml')
$env:GROK_MEMORY='0';$env:GROK_SUBAGENTS='0';$env:GROK_WEB_FETCH='0';$env:GROK_AGENT_DASHBOARD='0'
$si=[Diagnostics.ProcessStartInfo]::new('C:\Users\thoma\.grok\bin\grok.exe');$si.WorkingDirectory=$work;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
foreach($a in @('--model','grok-4.7-build-fast','--cwd',$work,'--session-id',[Guid]::NewGuid().ToString(),'--no-subagents','--disable-web-search','--permission-mode','plan','--tools','read_file','--disallowed-tools','read_file,Agent,run_terminal_cmd,search_replace,web_search,web_fetch,task,todo_write','--verbatim','--system-prompt-override','Tool-less exact-source patch author; output complete patch JSON and actual-import tests only.','--reasoning-effort','low','--max-turns','2','--output-format','json','--prompt-file',$pp)){$si.ArgumentList.Add($a)}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$clock=[Diagnostics.Stopwatch]::StartNew();$p.Start()|Out-Null
@{pid=$p.Id;model='grok-4.7-build-fast';source_sha256=$sha;deadline_seconds=360;credential_saved=$false;native_children_actual=0}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $work 'launch.json')
$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$killed=$false
while(!$p.WaitForExit(15000)){@{seconds=[math]::Round($clock.Elapsed.TotalSeconds);state='waiting'}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $work 'heartbeat.jsonl');if($clock.Elapsed.TotalSeconds-ge360){$p.Kill($true);$killed=$true;break}}
$p.WaitForExit();$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();$stdout|Set-Content -LiteralPath (Join-Path $work 'stdout.json');$stderr|Set-Content -LiteralPath (Join-Path $work 'stderr.txt');$state='NOT_ACCEPTED'
try{$r=$stdout|ConvertFrom-Json;$usage=$r.usage;$parsed=$r.text|ConvertFrom-Json;if(!$killed -and $p.ExitCode-eq0 -and $null-ne$parsed.replacements -and $parsed.test_source){$parsed|ConvertTo-Json -Depth 25|Set-Content -LiteralPath (Join-Path $work 'patch.json');$parsed.test_source|Set-Content -LiteralPath (Join-Path $work 'test_device_inventory.py');$state='COMPLETE_PATCH_UNTRUSTED'}}catch{}
@{requested_model='grok-4.7-build-fast';status=$state;pid=$p.Id;exit_code=$p.ExitCode;elapsed_seconds=[math]::Round($clock.Elapsed.TotalSeconds,2);outer_killed=$killed;usage=$usage;model_usage=$r.modelUsage;stop_reason=$r.stopReason;vendor_reported_cost_usd=$r.total_cost_usd}|ConvertTo-Json -Depth 15|Set-Content -LiteralPath (Join-Path $work 'terminal.json')
